#include <memory>

// This concept cannot be cleanly demonstrated with standard library code
// as auto_ptr_ref is an implementation detail, but the effect is visible:

std::auto_ptr<int> factory() {
    return std::auto_ptr<int>(new int(42));
}

int main() {
    // This initialization involves converting the rvalue temporary
    // returned by factory() via auto_ptr_ref to allow modification.
    std::auto_ptr<int> p1 = factory(); 

    // If p1 had been copied using a standard const reference copy ctor,
    // the resource would leak or be double-deleted.
    // auto_ptr_ref ensures the ownership is transferred correctly.
}
